  virtual ccxt::any parseTransactionStatus(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("Success"), std::string("ok")},
        {std::string("Succeed"), std::string("ok")},
        {std::string("Rejected"), std::string("failed")},
        {std::string("Security check failed"), std::string("failed")},
        {std::string("SecurityCheckFailed"), std::string("failed")},
        {std::string("Expired"), std::string("failed")},
        {std::string("Address Risk"), std::string("failed")},
        {std::string("Security Checking"), std::string("pending")},
        {std::string("SecurityChecking"), std::string("pending")},
        {std::string("Pending Review"), std::string("pending")},
        {std::string("Pending Transfer"), std::string("pending")},
        {std::string("AmlCsApporve"), std::string("pending")},
        {std::string("New"), std::string("pending")},
        {std::string("Confirmed"), std::string("pending")},
        {std::string("Cancelled"), std::string("canceled")},
    };
    return this->safeString(statuses, status, status);
  }

  ccxt::any parseTransaction(ccxt::any transaction,
                             ccxt::any currency = ccxt::any{},
                             ccxt::any p2 = ccxt::any{},
                             ccxt::any p3 = ccxt::any{}) override {
    //
    // withdraw
    //
    //     {
    //         "id": "10000001",
    //         "freezeId": null,
    //         "address": "44exxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
    //         "amountRv": "100",
    //         "chainCode": "11",
    //         "chainName": "TRX",
    //         "currency": "USDT",
    //         "currencyCode": 3,
    //         "email": "abc@gmail.com",
    //         "expiredTime": "0",
    //         "feeRv": "1",
    //         "nickName": null,
    //         "phone": null,
    //         "rejectReason": "",
    //         "submitedAt": "1670000000000",
    //         "submittedAt": "1670000000000",
    //         "txHash": null,
    //         "userId": "10000001",
    //         "status": "Success"
    //
    // fetchDeposits
    //
    //     {
    //         "id": "29200",
    //         "currency": "USDT",
    //         "currencyCode": "3",
    //         "chainName": "ETH",
    //         "chainCode": "4",
    //         "txHash":
    //         "0x0bdbdc47807769a03b158d5753f54dfc58b92993d2f5e818db21863e01238e5d",
    //         "address": "0x5bfbf60e0fa7f63598e6cfd8a7fd3ffac4ccc6ad",
    //         "amountEv": "3000000000",
    //         "confirmations": "13",
    //         "type": "Deposit",
    //         "status": "Success",
    //         "createdAt": "1592722565000",
    //     }
    //
    // fetchWithdrawals
    //
    //     {
    //         "id": "10000001",
    //         "userId": "10000001",
    //         "freezeId": "10000002",
    //         "phone": null,
    //         "email": "abc@gmail.com",
    //         "nickName": null,
    //         "currency": "USDT",
    //         "currencyCode": "3",
    //         "status": "Succeed",
    //         "withdrawStatus": "Succeed",
    //         "amountEv": "8800000000",
    //         "feeEv": "1200000000",
    //         "address": "0x5xxxad",
    //         "txHash: "0x0xxxx5d",
    //         "submitedAt": "1702571922000",
    //         "submittedAt": "1702571922000",
    //         "expiredTime": "0",
    //         "rejectReason": null,
    //         "chainName": "ETH",
    //         "chainCode": "4",
    //         "proxyAddress": null
    //     }
    //
    ccxt::any id = this->safeString(transaction, std::string("id"));
    ccxt::any address = this->safeString(transaction, std::string("address"));
    ccxt::any tag = ccxt::any{};
    ccxt::any txid = this->safeString(transaction, std::string("txHash"));
    ccxt::any currencyId =
        this->safeString(transaction, std::string("currency"));
    currency = this->safeCurrency(currencyId, currency);
    ccxt::any code = ::getValue(currency, std::string("code"));
    ccxt::any networkId =
        this->safeString(transaction, std::string("chainName"));
    ccxt::any timestamp =
        this->safeIntegerN(transaction, ccxt::list{std::string("createdAt"),
                                                   std::string("submitedAt"),
                                                   std::string("submittedAt")});
    ccxt::any type = this->safeStringLower(transaction, std::string("type"));
    ccxt::any feeCost = this->parseNumber(
        this->fromEn(this->safeString(transaction, std::string("feeEv")),
                     this->safeValue(currency, std::string("valueScale"))));
    if (isTrue(isEqual(feeCost, ccxt::any{}))) {
      feeCost = this->safeNumber(transaction, std::string("feeRv"));
    }
    ccxt::any fee = ccxt::any{};
    if (isTrue(!isEqual(feeCost, ccxt::any{}))) {
      type = std::string("withdrawal");
      fee = ccxt::dict{
          {std::string("cost"), feeCost},
          {std::string("currency"), code},
      };
    }
    ccxt::any status = this->parseTransactionStatus(
        this->safeString(transaction, std::string("status")));
    ccxt::any amount = this->parseNumber(
        this->fromEn(this->safeString(transaction, std::string("amountEv")),
                     this->safeValue(currency, std::string("valueScale"))));
    if (isTrue(isEqual(amount, ccxt::any{}))) {
      amount = this->safeNumber(transaction, std::string("amountRv"));
    }
    return ccxt::dict{
        {std::string("info"), transaction},
        {std::string("id"), id},
        {std::string("txid"), txid},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("network"), this->networkIdToCode(networkId, code)},
        {std::string("address"), address},
        {std::string("addressTo"), address},
        {std::string("addressFrom"), ccxt::any{}},
        {std::string("tag"), tag},
        {std::string("tagTo"), tag},
        {std::string("tagFrom"), ccxt::any{}},
        {std::string("type"), type},
        {std::string("amount"), amount},
        {std::string("currency"), code},
        {std::string("status"), status},
        {std::string("updated"), ccxt::any{}},
        {std::string("comment"), ccxt::any{}},
        {std::string("internal"), ccxt::any{}},
        {std::string("fee"), fee},
    };
  }

  /**
   * @method
   * @name phemex#fetchPositions
   * @description fetch all open positions
   * @see
   * https://github.com/phemex/phemex-api-docs/blob/master/Public-Contract-API-en.md#query-trading-account-and-positions
   * @see
   * https://github.com/phemex/phemex-api-docs/blob/master/Public-Hedged-Perpetual-API.md#query-account-positions
   * @see
   * https://phemex-docs.github.io/#query-account-positions-with-unrealized-pnl
   * @param {string[]} [symbols] list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.code] the currency code to fetch positions for,
   * USD, BTC or USDT, USDT is the default
   * @param {string} [params.method] *USDT contracts only*
   * 'privateGetGAccountsAccountPositions' or 'privateGetGAccountsPositions'
   * default is 'privateGetGAccountsAccountPositions'
   * @returns {object[]} a list of [position structure]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<ccxt::any>
  fetchPositions(ccxt::any symbols = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 symbols = this->marketSymbols(symbols);
                 ccxt::any subType = ccxt::any{};
                 ccxt::any code = this->safeString2(
                     params, std::string("currency"), std::string("code"),
                     std::string("USDT"));
                 params = this->omit(params, ccxt::list{std::string("currency"),
                                                        std::string("code")});
                 ccxt::any settle = ccxt::any{};
                 ccxt::any market = ccxt::any{};
                 ccxt::any firstSymbol = this->safeString(symbols, 0);
                 if (isTrue(!isEqual(firstSymbol, ccxt::any{}))) {
                   market = this->market(firstSymbol);
                   settle = ::getValue(market, std::string("settle"));
                   code = ::getValue(market, std::string("settle"));
                 } else {
                   ccxt::any settleparamsVariable = this->handleOptionAndParams(
                       params, std::string("fetchPositions"),
                       std::string("settle"), code);
                   settle = ::getValue(settleparamsVariable, 0);
                   params = ::getValue(settleparamsVariable, 1);
                 }
                 ccxt::any subTypeparamsVariable = this->handleSubTypeAndParams(
                     std::string("fetchPositions"), market, params);
                 subType = ::getValue(subTypeparamsVariable, 0);
                 params = ::getValue(subTypeparamsVariable, 1);
                 ccxt::any isUSDTSettled = isEqual(settle, std::string("USDT"));
                 if (isTrue(isUSDTSettled)) {
                   code = std::string("USDT");
                 } else if (isTrue(isEqual(settle, std::string("BTC")))) {
                   code = std::string("BTC");
                 } else if (isTrue(isEqual(code, ccxt::any{}))) {
                   code = (isTrue((isEqual(subType, std::string("linear"))))
                               ? ccxt::any(std::string("USD"))
                               : ccxt::any(std::string("BTC")));
                 }
                 ccxt::any currency = this->currency(code);
                 ccxt::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                 };
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isUSDTSettled)) {
                   ccxt::any method = ccxt::any{};
                   ccxt::any methodparamsVariable = this->handleOptionAndParams(
                       params, std::string("fetchPositions"),
                       std::string("method"),
                       std::string("privateGetGAccountsAccountPositions"));
                   method = ::getValue(methodparamsVariable, 0);
                   params = ::getValue(methodparamsVariable, 1);
                   if (isTrue(isEqual(
                           method,
                           std::string(
                               "privateGetGAccountsAccountPositions")))) {
                     response =
                         awaitValue(this->privateGetGAccountsAccountPositions(
                             this->extend(request, params)));
                   } else {
                     response = awaitValue(this->privateGetGAccountsPositions(
                         this->extend(request, params)));
                   }
                 } else {
                   response =
                       awaitValue(this->privateGetAccountsAccountPositions(
                           this->extend(request, params)));
                 }
                 //
                 //     {
                 //         "code":0,"msg":"",
                 //         "data":{
                 //             "account":{
                 //                 "accountId":6192120001,
                 //                 "currency":"BTC",
                 //                 "accountBalanceEv":1254744,
                 //                 "totalUsedBalanceEv":0,
                 //                 "bonusBalanceEv":1254744
                 //             },
                 //             "positions":[
                 //                 {
                 //                     "accountID":6192120001,
                 //                     "symbol":"BTCUSD",
                 //                     "currency":"BTC",
                 //                     "side":"None",
                 //                     "positionStatus":"Normal",
                 //                     "crossMargin":false,
                 //                     "leverageEr":100000000,
                 //                     "leverage":1.00000000,
                 //                     "initMarginReqEr":100000000,
                 //                     "initMarginReq":1.00000000,
                 //                     "maintMarginReqEr":500000,
                 //                     "maintMarginReq":0.00500000,
                 //                     "riskLimitEv":10000000000,
                 //                     "riskLimit":100.00000000,
                 //                     "size":0,
                 //                     "value":0E-8,
                 //                     "valueEv":0,
                 //                     "avgEntryPriceEp":0,
                 //                     "avgEntryPrice":0E-8,
                 //                     "posCostEv":0,
                 //                     "posCost":0E-8,
                 //                     "assignedPosBalanceEv":0,
                 //                     "assignedPosBalance":0E-8,
                 //                     "bankruptCommEv":0,
                 //                     "bankruptComm":0E-8,
                 //                     "bankruptPriceEp":0,
                 //                     "bankruptPrice":0E-8,
                 //                     "positionMarginEv":0,
                 //                     "positionMargin":0E-8,
                 //                     "liquidationPriceEp":0,
                 //                     "liquidationPrice":0E-8,
                 //                     "deleveragePercentileEr":0,
                 //                     "deleveragePercentile":0E-8,
                 //                     "buyValueToCostEr":100225000,
                 //                     "buyValueToCost":1.00225000,
                 //                     "sellValueToCostEr":100075000,
                 //                     "sellValueToCost":1.00075000,
                 //                     "markPriceEp":135736070,
                 //                     "markPrice":13573.60700000,
                 //                     "markValueEv":0,
                 //                     "markValue":null,
                 //                     "unRealisedPosLossEv":0,
                 //                     "unRealisedPosLoss":null,
                 //                     "estimatedOrdLossEv":0,
                 //                     "estimatedOrdLoss":0E-8,
                 //                     "usedBalanceEv":0,
                 //                     "usedBalance":0E-8,
                 //                     "takeProfitEp":0,
                 //                     "takeProfit":null,
                 //                     "stopLossEp":0,
                 //                     "stopLoss":null,
                 //                     "cumClosedPnlEv":0,
                 //                     "cumFundingFeeEv":0,
                 //                     "cumTransactFeeEv":0,
                 //                     "realisedPnlEv":0,
                 //                     "realisedPnl":null,
                 //                     "cumRealisedPnlEv":0,
                 //                     "cumRealisedPnl":null
                 //                 }
                 //             ]
                 //         }
                 //     }
                 //
                 ccxt::any data = this->safeValue(response, std::string("data"),
                                                  ccxt::dict{});
                 ccxt::any positions = this->safeValue(
                     data, std::string("positions"), ccxt::list{});
                 ccxt::any result = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(positions));
                      postFixIncrement(i)) {
                   ccxt::any position = ::getValue(positions, i);
                   arrayPush(result, this->parsePosition(position));
                 }
                 return this->filterByArrayPositions(
                     result, std::string("symbol"), symbols, false);
               })
        .share();
  }

  /**
   * @method
   * @name phemex#fetchPositionHistory
   * @description fetches historical positions
   * @see https://phemex-docs.github.io/#query-closed-positions
   * @param {string} symbol unified contract symbol
   * @param {int} [since] the earliest time in ms to fetch positions for
   * @param {int} [limit] the maximum amount of records to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch positions for
   * @returns {object[]} a list of [position structures]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<ccxt::any>
  fetchPositionHistory(ccxt::any symbol, ccxt::any since = ccxt::any{},
                       ccxt::any limit = ccxt::any{},
                       ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        symbol = ::getValue(market, std::string("symbol"));
                        ccxt::any request = ccxt::dict{
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                        };
                        if (isTrue(!isEqual(limit, ccxt::any{}))) {
                          ::setValue(request, std::string("limit"),
                                     mathMin(200, limit));
                        }
                        ccxt::any response = awaitValue(
                            this->privateGetApiDataGFuturesClosedPosition(
                                this->extend(request, params)));
                        //
                        //    {
                        //        "code": "0",
                        //        "msg": "OK",
                        //        "data": [
                        //            {
                        //                "symbol": "ETHUSDT",
                        //                "currency": "USDT",
                        //                "term": "0",
                        //                "closedSizeRq": "0.09",
                        //                "side": "1",
                        //                "cumEntryValueRv": null,
                        //                "closedPnlRv": "-0.1385",
                        //                "exchangeFeeRv": "0.2561889",
                        //                "fundingFeeRv": "0",
                        //                "realizedPnlRv": "-0.3946889",
                        //                "finished": "0",
                        //                "openedTimeNs": "1777998771316",
                        //                "updatedTimeNs": "1777998802592",
                        //                "openPrice": "2372.88888889",
                        //                "closePrice": "2371.35000000",
                        //                "roi": "-0.09702738",
                        //                "leverage": "-52.5"
                        //            },
                        //        ]
                        //    }
                        //
                        ccxt::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        ccxt::any positions =
                            this->parsePositions(data, ccxt::list{symbol});
                        return this->filterBySymbolSinceLimit(positions, symbol,
                                                              since, limit);
                      })
        .share();
  }

